  'M171.5 216.5Q170.0 219.0 170.0 222.5Q170.0 226.0 175.5 232.5Q181.0 239.0 184.5 241.0Q188.0 243.0 192.5 243.0Q197.0 243.0 199.5 241.0Q202.0 239.0 202.5 234.0Q203.0 229.0 198.0 223.0Q193.0 217.0 188.5 214.5Q184.0 212.0 180.5 212.0Q177.0 212.0 175.0 213.0Q173.0 214.0 171.5 216.5Z',
